"""Cuaderno del estudiante de 1.º medio Matemática, OA 15 (azar, tabla de Galton y paseos aleatorios): clases 1 a 5."""
from __future__ import annotations

from fractions import Fraction as F

from student_content_ma_m1_b import L
from student_lessons import arith, ex

OA15 = "MA1M OA 15"


def fr(value) -> str:
    """Fracción irreductible como texto: 3/8; un entero se escribe sin denominador."""
    return str(F(value))


FRAC = " Responde como fracción irreductible."

